1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	    }
28	    [data-color="red"] { --fg: #dc2626; }
29	    [data-color="green"] { --fg: #16a34a; }
30	    [data-color="amber"] { --fg: #d97706; }
31	    [data-color="violet"] { --fg: #7c3aed; }
32	    [data-color="cyan"] { --fg: #0891b2; }
33	    @media (prefers-color-scheme: dark) {
34	      :root {
35	        --bg: #111;
36	        --text: #d1d5db;
37	        --fg: #93c5fd;
38	        --shadow: rgba(0, 0, 0, 0.6);
39	        --kbd-bg: rgba(255, 255, 255, 0.15);
40	      }
41	      [data-color="red"] { --fg: #fca5a5; }
42	      [data-color="green"] { --fg: #86efac; }
43	      [data-color="amber"] { --fg: #fcd34d; }
44	      [data-color="violet"] { --fg: #c4b5fd; }
45	      [data-color="cyan"] { --fg: #67e8f9; }
46	    }
47	    @media (prefers-contrast: more) {
48	      :root {
49	        --shadow: rgba(0, 0, 0, 0.9);
50	      }
51	      .hint {
52	        opacity: 1;
53	      }
54	    }
55	    @media (forced-colors: active) {
56	      svg circle {
57	        stroke: CanvasText;
58	        stroke-width: 2;
59	      }
60	    }
61	    body {
62	      min-height: 100vh;
63	      min-height: 100dvh;
64	      display: grid;
65	      place-items: center;
66	      padding: 1rem;
67	      background: var(--bg);
68	      color: var(--text);
69	      font-family: system-ui, -apple-system, sans-serif;
70	    }
71	    main {
72	      width: 100%;
73	      display: flex;
74	      flex-direction: column;
75	      align-items: center;
76	      text-align: center;
77	    }
78	    button {
79	      display: block;
80	      width: min(360px, 100%, 60vh);
81	      aspect-ratio: 1;
82	      border: 0;
83	      border-radius: 50%;
84	      background: none;
85	      color: var(--fg);
86	      cursor: pointer;
87	      touch-action: manipulation;
88	      -webkit-tap-highlight-color: transparent;
89	      transition: color 0.4s ease;
90	    }
91	    .no-transition,
92	    .no-transition svg {
93	      transition: none !important;
94	    }
95	    button:focus-visible {
96	      outline: 3px solid currentColor;
97	      outline-offset: 8px;
98	    }
99	    svg {
100	      display: block;
101	      width: 100%;
102	      height: 100%;
103	      overflow: visible;
104	      opacity: 0.85;
105	      filter: drop-shadow(0 8px 16px var(--shadow));
106	      transition: opacity 0.3s ease;
107	      backface-visibility: hidden;
108	    }
109	    button:active svg,
110	    button:focus-visible svg {
111	      opacity: 1;
112	    }
113	    @keyframes pulse {
114	      0% {
115	        filter: drop-shadow(0 8px 16px var(--shadow)) drop-shadow(0 0 20px currentColor);
116	      }
117	      100% {
118	        filter: drop-shadow(0 8px 16px var(--shadow));
119	      }
120	    }
121	    @media (hover: hover) {
122	      button:hover svg {
123	        opacity: 1;
124	      }
125	    }
126	    @media (prefers-reduced-motion: no-preference) {
127	      svg {
128	        transition:
129	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
130	          opacity 0.3s ease;
131	      }
132	      button:focus-visible svg {
133	        transform: scale(1.05);
134	      }
135	      button:active svg {
136	        transform: scale(0.97);
137	      }
138	      button.color-changed svg {
139	        animation: pulse 0.5s ease-out;
140	      }
141	    }
142	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
143	      button:hover:not(:active) svg {
144	        transform: scale(1.05);
145	      }
146	    }
147	    .visually-hidden {
148	      position: absolute;
149	      width: 1px;
150	      height: 1px;
151	      overflow: hidden;
152	      clip-path: inset(50%);
153	      white-space: nowrap;
154	    }
155	    .status {
156	      margin-top: 2rem;
157	      font-weight: 600;
158	    }
159	    .hint {
160	      margin-top: 0.25rem;
161	      font-size: 0.875rem;
162	      opacity: 0.8;
163	    }
164	    @media (hover: none) and (pointer: coarse) {
165	      .hint .keys {
166	        display: none;
167	      }
168	    }
169	    kbd {
170	      display: inline-block;
171	      padding: 0.125rem 0.375rem;
172	      background: var(--kbd-bg);
173	      border: 1px solid transparent;
174	      border-radius: 0.25rem;
175	      font-family: monospace;
176	      font-size: 0.75em;
177	    }
178	  </style>
179	</head>
180	<body>
181	  <main>
182	    <h1 class="visually-hidden">Animated Circle</h1>
183	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
184	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
185	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
186	      </svg>
187	    </button>
188	    <p class="status" id="status" role="status" aria-atomic="true">Blue</p>
189	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle colors<span class="keys"> • <kbd>Shift</kbd> to reverse • <kbd>Arrows</kbd>/<kbd>Home</kbd>/<kbd>End</kbd> to navigate</span></p>
190	  </main>
191	  <script>
192	    const button = document.querySelector('button');
193	    const status = document.querySelector('.status');
194	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
195	    const storageKey = 'circle-color';
196	
197	    // Safely retrieve saved color from localStorage, returning null if unavailable
198	    function loadColor() {
199	      try {
200	        return localStorage.getItem(storageKey);
201	      } catch {
202	        return null;
203	      }
204	    }
205	
206	    // Safely save color to localStorage, silently failing if unavailable
207	    function saveColor(color) {
208	      try {
209	        localStorage.setItem(storageKey, color);
210	      } catch {}
211	    }
212	
213	    const savedColor = loadColor();
214	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
215	
216	    // Apply current color to button and update status display
217	    function applyColor() {
218	      const color = colors[index];
219	      if (color === 'blue') {
220	        delete button.dataset.color;
221	      } else {
222	        button.dataset.color = color;
223	      }
224	      status.textContent = color[0].toUpperCase() + color.slice(1);
225	    }
226	
227	    // Cycle color by step amount and trigger pulse animation
228	    function changeColor(step) {
229	      const next = (index + step + colors.length) % colors.length;
230	      // Home/End at the boundary shouldn't pulse or rewrite storage
231	      if (next === index) return;
232	      index = next;
233	      applyColor();
234	      saveColor(colors[index]);
235	
236	      button.classList.remove('color-changed');
237	      void button.offsetWidth;
238	      button.classList.add('color-changed');
239	    }
240	
241	    applyColor();
242	    // Double rAF ensures paint completes before enabling animations
243	    requestAnimationFrame(() => requestAnimationFrame(() => {
244	      button.classList.remove('no-transition');
245	    }));
246	
247	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
248	    const hoverQuery = matchMedia('(hover: none)');
249	    const verbSpan = document.querySelector('.hint .verb');
250	    function updateVerb() {
251	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
252	    }
253	    updateVerb();
254	    hoverQuery.addEventListener('change', updateVerb);
255	
256	    // Space and Enter activate through the native click, but keyboard-synthesized
257	    // clicks don't reliably carry shiftKey, so remember it from the key events
258	    let shiftHeld = false;
259	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
260	    button.addEventListener('keyup', (event) => {
261	      if (isActivationKey(event)) shiftHeld = event.shiftKey;
262	    });
263	    button.addEventListener('blur', () => {
264	      shiftHeld = false;
265	    });
266	
267	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
268	    button.addEventListener('keydown', (event) => {
269	      if (isActivationKey(event)) {
270	        shiftHeld = event.shiftKey;
271	        // Holding Enter would otherwise fire a click on every repeat
272	        if (event.repeat && event.key === 'Enter') event.preventDefault();
273	        return;
274	      }
275	      if (event.altKey || event.ctrlKey || event.metaKey) return;
276	      if (event.key in keySteps) {
277	        event.preventDefault();
278	        changeColor(keySteps[event.key]);
279	      } else if (event.key === 'Home') {
280	        event.preventDefault();
281	        changeColor(-index);
282	      } else if (event.key === 'End') {
283	        event.preventDefault();
284	        changeColor(colors.length - 1 - index);
285	      }
286	    });
287	    button.addEventListener('click', (event) => {
288	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
289	      shiftHeld = false;
290	    });
291	    button.addEventListener('animationend', () => {
292	      button.classList.remove('color-changed');
293	    });
294	    // Sync color across tabs when storage changes
295	    addEventListener('storage', (event) => {
296	      // key is null when another tab calls localStorage.clear()
297	      if (event.key !== storageKey && event.key !== null) return;
298	      const newIndex = colors.indexOf(event.newValue);
299	      index = newIndex === -1 ? 0 : newIndex;
300	      applyColor();
301	    });
302	  </script>
303	</body>
304	</html>
