// Space clicks on keyup; Enter already clicked on keydown, so updating
// shiftHeld on Enter's keyup would leak into the next mouse click
button.addEventListener('keyup', (event) => {
  if (event.key === ' ') shiftHeld = event.shiftKey;
});

